Write a Python function that takes in a list of strings and returns a list of strings where each string is the result of concatenating all of the elements in the input list.

Assistantassistant
from functools import reduce

def combine_texts(texts):
    if not texts:
        return []

    return reduce(lambda a, b: a + b, texts)

import collections

class Solution(object):
    def isAnagram(self, s, t):

        if len(s) != len(t):
            return False

        c = collections.Counter(s)

        for d in t:
            c[d] -= 1
            if c[d] <= -1:
                return False

        return True

